/// Runs copy-on-write mutations that do not enqueue system events. SessionStore
/// clones share the event sink, so event-producing transactions need a dedicated
/// commit path that cannot publish rolled-back events.
fn commit_store_mutation<ResultValue, Mutate>(
    store: &mut SessionStore,
    store_path: &Path,
    mutate: Mutate,
) -> Result<ResultValue, String>
where
    Mutate: FnOnce(&mut SessionStore) -> Result<ResultValue, String>,
{
    commit_store_mutation_with(
        store,
        mutate,
        |next_store| save_store(store_path, next_store),
        |next_store| verify_persisted_store_commit(store_path, next_store),
    )
}

fn commit_store_mutation_with<ResultValue, Mutate, Persist, VerifyAfterError>(
    store: &mut SessionStore,
    mutate: Mutate,
    persist: Persist,
    verify_after_error: VerifyAfterError,
) -> Result<ResultValue, String>
where
    Mutate: FnOnce(&mut SessionStore) -> Result<ResultValue, String>,
    Persist: FnOnce(&SessionStore) -> Result<(), String>,
    VerifyAfterError: FnOnce(&SessionStore) -> Result<bool, String>,
{
    let mut next_store = store.clone();
    let result = mutate(&mut next_store)?;
    if let Err(save_error) = persist(&next_store) {
        match verify_after_error(&next_store) {
            Ok(true) => {
                eprintln!(
                    "PortMate: store save returned an error, but the intended snapshot was verified on disk: {save_error}"
                );
            }
            Ok(false) => return Err(save_error),
            Err(verify_error) => {
                return Err(format!(
                    "{save_error}; 无法判定 Store 提交是否生效，请重启应用: {verify_error}"
                ));
            }
        }
    }
    *store = next_store;
    Ok(result)
}

fn verify_persisted_store_commit(path: &Path, expected: &SessionStore) -> Result<bool, String> {
    let persisted = read_persisted_store_for_migration(path)?;
    let persisted = serde_json::to_value(persisted)
        .map_err(|error| format!("failed to encode persisted Store for verification: {error}"))?;
    let expected = serde_json::to_value(expected)
        .map_err(|error| format!("failed to encode expected Store for verification: {error}"))?;
    if persisted != expected {
        return Ok(false);
    }

    let version = store_snapshot_version(path)?;
    if !matches!(version, StoreSnapshotVersion::Sha256(_)) {
        return Err("persisted Store exists but has no verifiable snapshot version".to_string());
    }
    STORE_SNAPSHOT_VERSIONS
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .map_err(|error| error.to_string())?
        .insert(path.to_path_buf(), version);
    Ok(true)
}

fn commit_tracked_store_mutation<ResultValue, Mutate>(
    store: &mut SessionStore,
    store_path: &Path,
    mutate: Mutate,
) -> Result<ResultValue, String>
where
    Mutate: FnOnce(&mut SessionStore) -> Result<(ResultValue, Vec<String>), String>,
{
    commit_tracked_store_mutation_with(
        store,
        mutate,
        |next_store| save_store(store_path, next_store),
        |next_store| verify_persisted_store_commit(store_path, next_store),
    )
}

fn commit_tracked_store_mutation_with<ResultValue, Mutate, Persist, VerifyAfterError>(
    store: &mut SessionStore,
    mutate: Mutate,
    persist: Persist,
    verify_after_error: VerifyAfterError,
) -> Result<ResultValue, String>
where
    Mutate: FnOnce(&mut SessionStore) -> Result<(ResultValue, Vec<String>), String>,
    Persist: FnOnce(&SessionStore) -> Result<(), String>,
    VerifyAfterError: FnOnce(&SessionStore) -> Result<bool, String>,
{
    let before = store.clone();
    let (result, event_ids) = mutate(store)?;
    if let Err(save_error) = persist(store) {
        match verify_after_error(store) {
            Ok(true) => {
                eprintln!(
                    "PortMate: tracked Store save returned an error, but the intended snapshot was verified on disk: {save_error}"
                );
            }
            Ok(false) => {
                for event_id in &event_ids {
                    store.discard_queued_system_event(event_id);
                }
                *store = before;
                return Err(save_error);
            }
            Err(verify_error) => {
                for event_id in &event_ids {
                    store.discard_queued_system_event(event_id);
                }
                *store = before;
                return Err(format!(
                    "{save_error}; 无法判定 Store 提交是否生效，请重启应用: {verify_error}"
                ));
            }
        }
    }
    Ok(result)
}

fn persist_applied_store(
    store: &SessionStore,
    store_path: &Path,
    operation: &str,
) -> Result<(), String> {
    persist_applied_store_with(
        store,
        operation,
        |next_store| save_store(store_path, next_store),
        |next_store| verify_persisted_store_commit(store_path, next_store),
    )
}

fn persist_applied_store_with<Persist, VerifyAfterError>(
    store: &SessionStore,
    operation: &str,
    persist: Persist,
    verify_after_error: VerifyAfterError,
) -> Result<(), String>
where
    Persist: FnOnce(&SessionStore) -> Result<(), String>,
    VerifyAfterError: FnOnce(&SessionStore) -> Result<bool, String>,
{
    let Err(save_error) = persist(store) else {
        return Ok(());
    };
    match verify_after_error(store) {
        Ok(true) => {
            eprintln!(
                "PortMate: {operation} save returned an error, but the intended snapshot was verified on disk: {save_error}"
            );
            Ok(())
        }
        Ok(false) => Err(save_error),
        Err(verify_error) => Err(format!(
            "{save_error}; 无法判定已应用的 {operation} 是否保存，请重启应用: {verify_error}"
        )),
    }
}

fn record_applied_system_event(
    state: &AppState,
    session_id: &str,
    message: String,
    operation: &str,
) {
    let mut store = match state.store.lock() {
        Ok(store) => store,
        Err(error) => {
            eprintln!("PortMate: {operation} succeeded but the system event lock failed: {error}");
            return;
        }
    };
    if let Err(error) = record_applied_system_event_with(
        &mut store,
        session_id,
        message,
        |next_store| save_store(&state.store_path, next_store),
        |next_store| verify_persisted_store_commit(&state.store_path, next_store),
    ) {
        eprintln!("PortMate: {operation} succeeded but system event persistence degraded: {error}");
    }
}

fn record_applied_system_event_with<Persist, VerifyAfterError>(
    store: &mut SessionStore,
    session_id: &str,
    message: String,
    persist: Persist,
    verify_after_error: VerifyAfterError,
) -> Result<(), String>
where
    Persist: FnOnce(&SessionStore) -> Result<(), String>,
    VerifyAfterError: FnOnce(&SessionStore) -> Result<bool, String>,
{
    let event_id = store
        .record_system_event_tracked(session_id, message)
        .ok_or_else(|| {
            format!("session profile unavailable after applied operation: {session_id}")
        })?;
    if let Err(error) = persist_applied_store_with(
        store,
        "applied operation event",
        persist,
        verify_after_error,
    ) {
        if let Some(event) = store.events.iter_mut().find(|event| event.id == event_id) {
            append_logging_error(event, format!("store save failed: {error}"));
        }
        return Err(error);
    }
    Ok(())
}

fn delete_host_keys_from_store(store: &mut SessionStore, key_ids: &[String]) -> HostKeyStore {
    store
        .host_keys
        .keys
        .retain(|key| !key_ids.contains(&key.id));
    for profile in &mut store.profiles {
        if let ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) = &mut profile.connection {
            ssh.trusted_host_keys
                .retain(|key| !key_ids.contains(&key.id));
        }
    }
    store.host_keys.clone()
}

#[tauri::command]
fn update_host_key(
    state: State<'_, AppState>,
    request: HostKeyUpdateRequest,
) -> Result<HostKeyStore, String> {
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    commit_store_mutation(&mut store, &state.store_path, |next_store| {
        update_host_key_in_store(next_store, request)
    })
}

fn update_host_key_in_store(
    store: &mut SessionStore,
    request: HostKeyUpdateRequest,
) -> Result<HostKeyStore, String> {
    if request.expected_key.id != request.key_id {
        return Err("expectedKey 与更新目标不是同一个 host key".to_string());
    }
    let alias = request.alias.trim().to_string();
    if alias.is_empty() {
        return Err("host key alias 不能为空".to_string());
    }
    let host = request.host.trim().to_string();
    if host.is_empty() {
        return Err("host key host 不能为空".to_string());
    }
    if request.port == 0 {
        return Err("host key 端口必须在 1-65535 之间".to_string());
    }
    let profile_id = request
        .profile_id
        .as_deref()
        .map(str::trim)
        .filter(|profile_id| !profile_id.is_empty())
        .map(str::to_string);
    let label = request
        .label
        .as_deref()
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .map(str::to_string);

    let current_key = store
        .host_keys
        .keys
        .iter()
        .find(|key| key.id == request.key_id)
        .cloned()
        .ok_or_else(|| format!("unknown host key: {}", request.key_id))?;
    let mut incoming_key = request.expected_key.clone();
    incoming_key.profile_id = profile_id;
    incoming_key.alias = alias;
    incoming_key.host = host;
    incoming_key.port = request.port;
    incoming_key.scope = request.scope;
    incoming_key.label = label;
    let merged_key =
        merge_expected_host_key_update(&current_key, &request.expected_key, incoming_key)?;
    if merged_key.scope == HostKeyScope::Profile {
        let Some(profile_id) = merged_key.profile_id.as_deref() else {
            return Err("Profile scope host key 必须选择 Profile".to_string());
        };
        if store.profile(profile_id).is_none() {
            return Err(format!("unknown session: {profile_id}"));
        }
    } else if let Some(profile_id) = merged_key.profile_id.as_deref() {
        if store.profile(profile_id).is_none() {
            return Err(format!("unknown session: {profile_id}"));
        }
    }

    let Some(key) = store
        .host_keys
        .keys
        .iter_mut()
        .find(|key| key.id == request.key_id)
    else {
        return Err(format!("unknown host key: {}", request.key_id));
    };
    apply_host_key_editable_fields(key, &merged_key);

    for profile in &mut store.profiles {
        if let ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) = &mut profile.connection {
            for profile_key in &mut ssh.trusted_host_keys {
                if profile_key.id == request.key_id {
                    apply_host_key_editable_fields(profile_key, &merged_key);
                }
            }
        }
    }

    Ok(store.host_keys.clone())
}

fn merge_expected_host_key_update(
    current_key: &TrustedHostKey,
    expected_key: &TrustedHostKey,
    incoming_key: TrustedHostKey,
) -> Result<TrustedHostKey, String> {
    if current_key.id != incoming_key.id || expected_key.id != incoming_key.id {
        return Err("expectedKey 与更新目标不是同一个 host key".to_string());
    }
    let expected = serde_json::to_value(expected_key)
        .map_err(|error| format!("序列化 expectedKey 失败: {error}"))?;
    let current = serde_json::to_value(current_key)
        .map_err(|error| format!("序列化当前 host key 失败: {error}"))?;
    let incoming = serde_json::to_value(&incoming_key)
        .map_err(|error| format!("序列化待更新 host key 失败: {error}"))?;
    let merged = merge_expected_json_value("Host Key", "hostKey", &expected, &current, &incoming)?;
    serde_json::from_value(merged)
        .map_err(|error| format!("反序列化合并后的 host key 失败: {error}"))
}

fn apply_host_key_editable_fields(target: &mut TrustedHostKey, source: &TrustedHostKey) {
    target.profile_id.clone_from(&source.profile_id);
    target.alias.clone_from(&source.alias);
    target.host.clone_from(&source.host);
    target.port = source.port;
    target.scope = source.scope;
    target.label.clone_from(&source.label);
}

