    #[test]
    fn remote_copy_markers_parse_latest_progress() {
        let output = b"__PORTMATE_SIZE__4096\n__PORTMATE_RESUME__512\n__PORTMATE_PROGRESS__512\n__PORTMATE_PROGRESS__2048\n__PORTMATE_DONE__4096\n";
        assert_eq!(
            remote_copy_markers(output),
            RemoteCopyMarkers {
                total: Some(4096),
                resume: Some(512),
                progress: Some(2048),
                done: Some(4096)
            }
        );
    }

    #[test]
    fn remote_copy_markers_require_monotonic_consistent_progress() {
        let reported = RemoteCopyMarkers {
            total: Some(4096),
            resume: Some(512),
            progress: Some(2048),
            done: None,
        };
        validate_remote_copy_markers(&reported, &reported).unwrap();
        validate_remote_copy_markers(
            &RemoteCopyMarkers {
                progress: Some(3072),
                ..reported
            },
            &reported,
        )
        .unwrap();

        for (markers, expected) in [
            (
                RemoteCopyMarkers {
                    total: Some(8192),
                    ..reported
                },
                "size marker changed",
            ),
            (
                RemoteCopyMarkers {
                    resume: Some(1024),
                    ..reported
                },
                "resume marker changed",
            ),
            (
                RemoteCopyMarkers {
                    progress: Some(1024),
                    ..reported
                },
                "progress marker moved backwards",
            ),
            (
                RemoteCopyMarkers {
                    progress: Some(8192),
                    ..reported
                },
                "progress marker 8192 exceeds size 4096",
            ),
            (
                RemoteCopyMarkers {
                    done: Some(3072),
                    ..reported
                },
                "done marker 3072 does not match size 4096",
            ),
        ] {
            let error = validate_remote_copy_markers(&markers, &reported).unwrap_err();
            assert!(error.contains(expected), "{error}");
        }
    }

